   "title": "消费金融从“拼规模”转向“拼健康”，招联主动压降总体规模",
   "summary": "《金融时报》报道，2026年消金行业告别高速增长，转向精细化运营。招联金融表示坚持“质量、效益、规模、结构”多目标平衡，主动压降总体规模，2026年上半年信用减值损失同比下降18.48%，拨备率远高于行业平均。",
   "decision": "印证招联当前“质量优先于规模”的战略，与启停机制V3.0控制粗放扩张、强化核心风控的方向一致，可作为对外沟通与内部定调的素材。",
