   "summary": "受美联储利率路径预期转鹰、美元与实际利率上行、地缘避险溢价回吐及多头获利了结等影响，COMEX金失守3900美元/盎司。董希淼认为短期或维持震荡放大，但长期支撑逻辑未被破坏。",
   "decision": "金价回调影响居民避险与消费意愿，招联消费信贷需求端或受财富效应波动扰动，需关注高净值客群还款能力变化。",
