   "title": "招联消费金融金融借款合同纠纷案11月2日在上海宝山法院开庭",
   "summary": "招联消费金融作为原告起诉自然人何某金融借款合同纠纷，案号(2026)沪0113民初35311号，11月2日14:10在上海市宝山区人民法院第九法庭开庭，属消费金融机构通过司法途径维护债权的常规程序性动作。",
   "decision": "招联自有债权维权节奏正常，印证消金行业“合规催收+司法诉调”常态化；启停机制V3.0对存量逾期处置与合规边界需同步校准。",
   "source": "新浪财经",
