   "title": "10月国内造车新势力销量出炉 比亚迪49万领跑 小米小鹏首破5万",
   "summary": "国内车企10月销量：比亚迪超49万辆同比+11%领跑，上汽43万辆紧随；零跑交付破10万居新势力首位，小鹏、小米首次站上5万辆。汽车业“金九银十”现象首次基本消失，行业分化加剧。",
   "decision": "汽车消费金融仍是招联重点场景，但行业降价内卷、销量见顶提示需严控车分期客群资质与残值风险。",
