   "summary": "近期汇丰、渣打、永丰、东亚等外资银行密集上架人民币大额存单，部分三年期产品利率较同期限国有大行高出近40个基点；10月以来多家股份行、民营银行也相继发行三年期、五年期大额存单。",
   "decision": "存款端竞争加剧、利率分化，招联负债端可关注同业与市场化资金来源成本走势，灵活配置期限结构。",
