   "summary": "多家券商基金接到通知，11月2日央行、证监会召开会议研究推动支持资本市场工具使用；同日三部门召集各大银行研究优化股票回购增持再贷款政策，被解读为金融管理部门进一步稳市场、稳预期的政策注脚。",
   "decision": "回购增持再贷款扩容利好央企估值与资本市场稳定，招联可关注联通体系内资本运作与股东协同机会。",
