   "summary": "国家发改委通知，自10月29日24时起国内汽、柴油标准品价格每吨应上调440元、420元，调控后实际上调345元、335元，折合92号汽油、95号汽油、0号柴油每升分别上调0.26、0.28、0.28元。",
   "decision": "油价上调直接抬升家庭出行与物流成本，对消费意愿有轻微抑制作用，消费金融需关注居民端偿债边际变化。",
