   "summary": "商务部、发改委、生态环境部、海关总署联合印发通知，从货物贸易升级、服务贸易便利、新业态新模式三方面提出16项措施，涵盖LNG期货保税交割、汽车测试零部件进口试点、人民币计价易货贸易等。",
