   "summary": "广西财政厅消息，2025年发放育儿补贴49.53亿元、惠及155万名婴幼儿、发放率100%；2026年已筹措下达育儿补贴资金46.15亿元，截至9月底累计发放39.58亿元、惠及128.09万名婴幼儿，每孩每年发放3600元，依托“一卡通”直达账户。",
   "decision": "育儿补贴“直达账户”，建宝家庭可关注本地申领；预产期临近，提前备好“一卡通”申报材料。",
