   "title": "广西育儿补贴申请时限延长至2026年12月31日，覆盖2022-2024出生婴幼儿",
   "summary": "广西卫健委新闻发布会透露，2022年至2024年符合条件的婴幼儿，首次育儿补贴申请截止时间延长至2026年12月31日，仅延长首次申请时限；广西育儿家庭每月多300元补贴，婚假新增15天，辅助生殖与无痛分娩纳入报销。",
   "decision": "若身边亲友有2022-2024年出生宝宝尚未申领，可提示其在12月31日前补办，避免错过补贴窗口。",
   "source": "南国早报/今日头条",
