   "title": "广西三孩家庭购房多补1万元 初育多补3000元",
   "summary": "广西在生育支持中自9月25日起开展新一轮购房补贴，初育家庭多补3000元、二孩多补5000元、三孩多补1万元，可与卖旧买新、高校毕业生等补贴叠加；公租房对多子女家庭优先配租、优先匹配户型。",
   "decision": "若未来考虑换房或改善居住，可关注属地多子女家庭购房补贴与公租房优先政策，提前规划家庭资产配置。",
