   "title": "普惠托育扩容：内蒙古建成“萌宝驿站”149家，千人口托位数达4.58",
   "summary": "内蒙古全面推开“萌宝驿站”社区托育建设，全区建成149家；18家医疗卫生机构单独提供普惠托育，9家用人单位创建全国爱心托育用人单位。全区千人口托位数由2020年1.2个提升至2025年4.58个。",
   "decision": "社区普惠托育网络完善，未来宝宝“开心”入托可选就近普惠点位，提前了解属地托育资源。",
