   "title": "育儿补贴信息管理系统新增“一键续领”功能",
   "summary": "国家卫健委介绍，育儿补贴信息管理系统2026年持续优化，新增“一键续领”功能，群众可便捷完成续领申请；2023、2024年出生婴幼儿续领时间安排以户籍省份政务平台提示为准。",
   "decision": "续领流程线上化、一键化，宝宝“开心”未来每年补贴续领可省心操作，建议绑定微信/支付宝小程序及时提醒。",
