   "summary": "国家中医药局、国家卫健委联合印发通知，加强基层中医适宜技术（含少数民族医）推广应用：国家设推广指导中心与师资库，省级建推广中心，到2030年县级中医适宜技术推广中心基本实现全覆盖。",
   "decision": "孕产期与育儿阶段可善用基层中医适宜技术服务（如产后调理、小儿保健），关注居住地社区中医资源可及性。",
