   "summary": "民政部印发通知启动'寒冬送温暖'专项救助行动，要求建立气象预警联动机制，联合公安、城管、卫健、应急等部门开展联合巡查，重点对车站码头、地下通道、桥梁涵洞等露宿区域拉网式排查，对危重患者按'先救治、后救助'原则送医。",
