   "summary": "美国中期选举于11月3日举行，改选众议院全部435席、参议院35席及36个州长；主流民调预测民主党有望夺取众议院，参议院胜负难料，结果将重写特朗普未来两年施政空间。",
   "decision": "美国权力格局变化或影响对华关税、科技与金融制裁走向，招联需关注外部环境对消费金融资金成本与合规的潜在外溢。",
