   "title": "社保缴费违法纳入全国税务处罚裁量基准，单位欠缴最高罚3倍",
   "summary": "《全国税务行政处罚裁量基准（2026年版）》11月1日施行，社保缴费违法行为首次纳入全国统一税务行政处罚裁量体系，用人单位欠缴社保最高可处三倍罚款，且“自愿放弃社保协议”不具备法律效力。",
   "decision": "家庭与招联作为用人单位均需依法足额缴纳社保，避免三倍罚款与合规风险；也提示代理商用工合规。",
   "source": "澎湃新闻",
