   "summary": "伴随《扩大消费“十五五”规划》，旅游强国、国民健康、民政事业等专项规划陆续出台，拓展夜游、研学、健康体检、康复疗养、普惠养老托育等服务消费新场景，消费规划体系立体丰富。",
   "decision": "服务消费场景扩容，招联可关注文旅、健康、托育等细分消费分期与场景金融机会。",
