   "summary": "中国共产党第二十届中央委员会第五次全体会议于10月26日至29日在北京举行，审议通过《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。全会决定，中国共产党第二十一次全国代表大会于2027年下半年在北京召开。",
   "decision": "全会定调'十五五'开局与治党基调，宏观政策连续性与改革方向对明年经济与市场预期有指引意义。",
