   "summary": "苏丹东部卡萨拉州两处、北部北方州一处发电站11月2日遭无人机袭击严重受损，导致东部和北部大范围停电，此前已有至少15处发电站遇袭。同日伊朗革命卫队称首支“为伊朗捐躯”旅已完成组建并接受强化训练，目前正准备实战与野外训练。",
