   "summary": "《全国税务行政处罚裁量基准（2026年版）》11月1日施行，社保缴费违法首次纳入全国统一税务处罚裁量体系，用人单位欠缴社保最高处三倍罚款，且“自愿放弃社保协议”不具备法律效力。",
