   "title": "致残风险防控：推进慢性病筛查与脑卒中、老年痴呆防控",
   "summary": "《人民日报》民生一线报道，残疾预防需政府、社会与个人共同努力，建议推进慢性病高危人群常态化筛查、医疗机构落实功能评估与早期康复转介，并开展脑卒中综合防控与老年期痴呆筛查干预，减少功能损伤。",
